import { useEffect, useRef } from "react";
import { AccessibilityInfo, Platform } from "react-native";

/**
 * Speak `text` at low priority after current speech. react-native-web has no
 * `announceForAccessibilityWithOptions`; calling it there threw inside an
 * effect and unmounted the whole screen, so fall back to the plain call.
 * Qt supports priority but no native announcement queue; request low priority
 * there without claiming that speech is queued behind another announcement.
 */
export function announce(text: string): void {
  const info: Partial<typeof AccessibilityInfo> = AccessibilityInfo;
  if (typeof info.announceForAccessibilityWithOptions === "function") {
    const qt=String(Platform.OS)==="qnx"||String(Platform.OS)==="marathon";
    info.announceForAccessibilityWithOptions(text, qt?{priority:"low"}:{queue:true,priority:"low"});
  } else {
    info.announceForAccessibility?.(text);
  }
}

/**
 * Announce `status` on iOS each time it changes after mount. Android and web
 * already speak it through the `accessibilityLiveRegion` on the status text;
 * VoiceOver ignores live regions, so without this it heard no phase change.
 */
export function useStatusAnnouncement(status: string): void {
  const previous = useRef(status);
  useEffect(() => {
    if (previous.current === status) return;
    previous.current = status;
    if (Platform.OS === "ios") announce(status);
  }, [status]);
}

import {Button} from '@/components/nyc-tron/ui/components/Button';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
/**
 * Plugin preset browser (roster E-23).
 *
 * Structural references pulled from Mobbin (structure only; Mobbin has no
 * GarageBand, BandLab, Logic Remote, Koala or Ableton Note screens, so these
 * are the closest matches it returned):
 * - Shopify, category picker: search field above a single-choice radio list.
 * - Oura, Soundscapes: sound list with the current choice checked in place.
 * - Brink, Genres filter: search field plus a list of single-line rows with radio marks.
 * - Discord, Soundboard: "Find the perfect sound" search above a sound grid.
 */
import { useRef } from "react";
import { I18nManager, Platform, Pressable, Text, TextInput, View, type KeyDownEvent, type ViewProps } from "react-native";
import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { useStatusAnnouncement } from "@/components/nyc-tron/ui/components/forge/announce";
import { INSERT_KIND_LABELS, filterPresets, type InsertKind, type InsertPreset } from "@/components/nyc-tron/ui/components/forge/audio/inserts";
import { space, radius, font, border, opacity, size } from '@/components/nyc-tron/ui/tokens';

const HIT = 44;

/** Load state of the preset list passed to {@linkcode PluginPresetBrowser}. */
export type PresetListStatus = "loading" | "error" | "ready";

/** Props for {@linkcode PluginPresetBrowser}. */
export interface PluginPresetBrowserProps extends Omit<ViewProps, "children">,ScopedControlProps {
  /** Effect type whose presets are listed. Names the heading and the list. */
  readonly kind: InsertKind;
  /** Presets for `kind`, factory first, in display order. */
  readonly presets: readonly InsertPreset[];
  /** Preset the slot was last set from. Marked as the checked radio. */
  readonly currentId?: string;
  /**
   * Once per press or arrow key with the chosen preset. Pressing the
   * current preset applies it again, which resets parameters edited since.
   * A rejected promise leaves `currentId` unchanged on screen.
   */
  readonly onApply: (presetId: string,transaction?:{undoGroup:string}) => void | Promise<unknown>;
  /** @default "ready" */
  readonly status?: PresetListStatus;
  readonly onSave?:(name:string)=>void|Promise<unknown>;
  readonly comparison?:{active:'A'|'B';hasA:boolean;hasB:boolean;onCapture:(slot:'A'|'B')=>void|Promise<unknown>;onRecall:(slot:'A'|'B')=>void|Promise<unknown>};
  /** Shown as a Retry button when `status` is `"error"`. */
  readonly onRetry?: () => void;
  /** @default false */
  readonly disabled?: boolean;
  className?: string;
  /** Drop the default token recipe; supply a full app recipe via `className`. */
  unstyled?: boolean;
}

/**
 * Controlled preset list for one insert effect, with a label search.
 * Presets are radios in one group: press to apply, or move with the arrow
 * keys, which applies each preset reached so it can be heard in place.
 * Loading and error states say what is happening; nothing is listed while
 * presets load.
 */
export function PluginPresetBrowser({scope='PluginPresetBrowser',revision=0,...props}:PluginPresetBrowserProps){
 const transaction=useRef(0);
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.kind,props.status,props.disabled,props.disabledReason,props.presets.map(p=>p.id)]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <PluginPresetBrowserBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onApply={id=>guard.run('onApply',h=>h.onApply(id,{undoGroup:owner+':preset:'+String(++transaction.current)}))}
  onSave={props.onSave?name=>guard.run('save',h=>h.onSave?.(name)):undefined}
  comparison={props.comparison?{...props.comparison,onCapture:slot=>guard.run('capture',h=>h.comparison?.onCapture(slot)),onRecall:slot=>guard.run('recall',h=>h.comparison?.onRecall(slot))}:undefined}
  onRetry={props.onRetry?(...args:Parameters<NonNullable<PluginPresetBrowserProps['onRetry']>>)=>guard.run('onRetry',h=>h.onRetry?.(...args)):undefined}
 />;
}
function PluginPresetBrowserBody({actionError,disabledReason,
  kind, presets, currentId, onApply, status = "ready", onRetry, disabled = false,onSave,comparison,
  className, unstyled = false, ...rest
}: PluginPresetBrowserProps&{actionError?:string|null}) {
  if(presets.length>4096||new Set(presets.map(p=>p.id)).size!==presets.length||presets.some(p=>!p.id.trim()||p.id.length>512||!p.label.trim()||p.label.length>1024))throw new RangeError('Invalid preset catalog');
  const styled = !unstyled;
  const local = useRef<StoreApi<{ query: string;name:string }> | null>(null);
  if (!local.current) local.current = createStore(() => ({ query: "",name:"" }));
  const store = local.current;
  const query = useStore(store, s => s.query);
  const saveName=useStore(store,s=>s.name);
  const refs = useRef(new Map<string, { focus?: () => void } | null>());
  const name = INSERT_KIND_LABELS[kind];
  const shown = filterPresets(presets, query);
  const statusText = status === "loading" ? `Loading ${name} presets` : status === "error" ? `${name} presets could not be loaded` : "";
  useStatusAnnouncement(statusText);

  const apply = (id: string) => { if (!disabled) void onApply(id); };
  const onKeyDown = (e: KeyDownEvent) => {
    const key = e.nativeEvent.key;
    const rtl = I18nManager.isRTL || (Platform.OS === "web" && typeof document !== "undefined" && document.documentElement.dir === "rtl");
    const dir = key === "ArrowDown" || key === (rtl ? "ArrowLeft" : "ArrowRight") ? 1
      : key === "ArrowUp" || key === (rtl ? "ArrowRight" : "ArrowLeft") ? -1 : 0;
    if (dir === 0 || disabled || shown.length === 0) return;
    e.preventDefault();
    const at = shown.findIndex(p => p.id === currentId);
    const next = shown[at < 0 ? (dir > 0 ? 0 : shown.length - 1) : (at + dir + shown.length) % shown.length];
    apply(next.id);
    refs.current.get(next.id)?.focus?.();
  };

  const muted = joinClasses(styled && "text-text-muted text-sm");
  const body = joinClasses(styled && "text-text");
  const checkedVisible = shown.some(p => p.id === currentId);
  let content;
  if (status === "loading") {
    content = <Text accessibilityLiveRegion="polite" {...{ className: muted }} style={{ paddingVertical: space[3] }}>{statusText}…</Text>;
  } else if (status === "error") {
    content = <View style={{ gap: space[2], paddingVertical: space[2], alignItems: "flex-start" }}>
      <Text accessibilityLiveRegion="polite" {...{ className: body }}>{`${statusText}. The effect keeps its current settings.`}</Text>
      {onRetry ? <Pressable role="button" accessibilityLabel={`Retry loading ${name} presets`} onPress={onRetry}
        {...{ className: joinClasses(styled && "rounded-control border border-border bg-surface-sunken items-center justify-center focus-visible:ring-2 focus-visible:ring-focus active:opacity-80") }}
        style={{ minHeight: HIT, paddingHorizontal: space[4] }}>
        <Text {...{ className: joinClasses(styled && "text-text font-semibold") }}>Retry</Text>
      </Pressable> : null}
    </View>;
  } else if (presets.length === 0) {
    content = <Text {...{ className: muted }} style={{ paddingVertical: space[3] }}>{`No presets for ${name} yet.`}</Text>;
  } else {
    content = <>
      <TextInput value={query} onChangeText={q => store.setState({ query: q })}
        accessibilityLabel={`Search ${name} presets`} placeholder="Search presets"
        autoCorrect={false} autoCapitalize="none" editable={!disabled} {...{ inputMode: "search" }}
        {...{ className: joinClasses(styled && "rounded-control border border-border bg-surface-sunken text-text placeholder:text-text-muted focus-visible:ring-2 focus-visible:ring-focus") }}
        style={{ minHeight: HIT, paddingHorizontal: space[3], fontSize: font[16], opacity: disabled ? opacity[45] : 1 }} />
      {shown.length === 0
        ? <View style={{ gap: space[2], alignItems: "flex-start", paddingVertical: space[1] }}>
            <Text accessibilityLiveRegion="polite" {...{ className: body }}>{`No ${name} presets match "${query.trim()}".`}</Text>
            <Pressable role="button" onPress={() => store.setState({ query: "" })}
              {...{ className: joinClasses(styled && "rounded-control border border-border items-center justify-center focus-visible:ring-2 focus-visible:ring-focus active:opacity-80") }}
              style={{ minHeight: HIT, paddingHorizontal: space[4] }}>
              <Text {...{ className: joinClasses(styled && "text-text font-semibold") }}>Clear search</Text>
            </Pressable>
          </View>
        : <View accessibilityLabel={`${name} presets`} {...{ role: "radiogroup" }}>
            {shown.map((preset, i) => {
              const checked = preset.id === currentId;
              const tabStop = checked || (!checkedVisible && i === 0);
              return <Pressable key={preset.id} ref={r => { refs.current.set(preset.id, r); }}
                role="radio" aria-checked={checked} accessibilityState={{ checked, disabled }}
                accessibilityLabel={preset.label} disabled={disabled} focusable={tabStop && !disabled}
                {...(Platform.OS === "web" ? { tabIndex: tabStop && !disabled ? 0 : -1 } : {})}
                onPress={() => apply(preset.id)} onKeyDown={onKeyDown}
                {...{ className: joinClasses(styled && "rounded-control focus-visible:ring-2 focus-visible:ring-focus active:opacity-80",
                  styled && checked && "bg-surface-sunken") }}
                style={{ minHeight: HIT, flexDirection: "row", alignItems: "center", gap: space[3], paddingHorizontal: space[2.5], opacity: disabled ? opacity[45] : 1 }}>
                <View pointerEvents="none" style={{ width: 20, height: 20, borderRadius: radius[10], borderWidth: border[2], alignItems: "center", justifyContent: "center" }}
                  {...{ className: joinClasses(styled && (checked ? "border-primary" : "border-text-muted")) }}>
                  {checked ? <View style={{ width: 10, height: 10, borderRadius: radius[5] }} {...{ className: joinClasses(styled && "bg-primary") }} /> : null}
                </View>
                <Text numberOfLines={1} style={{ flex: 1 }} {...{ className: joinClasses(styled && "text-text", styled && checked && "font-semibold") }}>{preset.label}</Text>
                {checked ? <Text {...{ className: muted }}>Current</Text> : null}
              </Pressable>;
            })}
          </View>}
    </>;
  }
  return <View {...rest} accessibilityLabel={`${name} preset browser`} {...{ role: "group" }}
    {...{ className: joinClasses(styled && "rounded-card border border-border bg-surface-raised", className) }}
    style={[{ padding: space[3], gap: space[2.5] }, rest.style]}>
    <Text role="heading" {...{ "aria-level": 3 }} {...{ className: joinClasses(styled && "text-text font-semibold text-base") }}>{`${name} presets`}</Text>
    {comparison?<View style={{gap:space[1.5]}}><Text {...{className:body}}>Comparison: {comparison.active}</Text><View style={{flexDirection:'row',flexWrap:'wrap',gap:space[1.5]}}>{(['A','B'] as const).map(slot=><View key={slot} style={{gap:space[1.5]}}><Button title={'Capture '+slot} disabled={disabled} unstyled={unstyled} onPress={()=>comparison.onCapture(slot)}/><Button title={'Recall '+slot} disabled={disabled||!(slot==='A'?comparison.hasA:comparison.hasB)} unstyled={unstyled} onPress={()=>comparison.onRecall(slot)}/></View>)}</View></View>:null}
    {onSave?<View style={{gap:space[1.5]}}><TextInput accessibilityLabel="New preset name" value={saveName} maxLength={256} editable={!disabled} onChangeText={name=>store.setState({name})} style={{minHeight:size.touch,padding:space[2]}} {...{className:body}}/><Button title="Save current settings as preset" disabled={disabled||!saveName.trim()} unstyled={unstyled} onPress={()=>onSave(saveName.trim())}/></View>:null}
    {content}
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

